import math

def find_largest_palindromic_cube(N: int) -> None:
    palindromic_cubes = []
    for i in range(math.floor(N**(1/3)) + 1):
        cube = i**3
        if cube <= N:
            if str(cube) == str(cube)[::-1]:
                palindromic_cubes.append(cube)

    if palindromic_cubes:
        print(max(palindromic_cubes))
    else:
        print("No palindromic cube exists below", N)

# Example usage:
N = int(input())
find_largest_palindromic_cube(N)
